"""Add replay runs: the per-project budget ledger for replaying a stored request.

Revision ID: 1002
Revises: 1001
Create Date: 2026-10-17

A replay sends a stored LLM request once more through a project credential. It is a paid call a
member can repeat with one click, so every replay is a row here and runs under an ADR 0015
reservation scoped per project per UTC month, exactly like a judge call in `evaluator_runs`.

Choices worth knowing about:

* Ids are UUIDv7 generated by the application, so `id` has no default.
* `source_trace_id` and `source_span_id` are plain text, not foreign keys: retention may delete
  the source span while the run must stay on the ledger. The same holds for the result ids.
* `requested_by` and `credential_id` are `ON DELETE SET NULL`; the run outlives both the user
  and the credential. `requested_by` is indexed so removing a user does not scan the table.
* `fidelity` and `status` are CHECKs over fixed lists. `error` is capped at 500 characters: it
  holds a run-level string, never a provider body. `reserved_usd` and `cost_usd` are never
  negative and default to 0, which here means "nothing reserved or charged", not "unknown".
* Three indexes: the span panel's "Replays" tab reads by source span, the month sum reads by
  project and time, and the reaper reads the running rows only (partial index).
* Row-level security is enabled and forced with the `0505` project isolation and worker bypass
  expressions.

The migration is one transaction creating one table under a 5 s lock timeout. Downgrade drops it.
"""

from collections.abc import Sequence

from alembic import op

revision: str = "1002"
down_revision: str | None = "1001"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None

LOCK_TIMEOUT = "5s"
PROJECT_EXPRESSION = (
    "project_id = (SELECT NULLIF(current_setting('app.project_id', true), '')::uuid)"
)
BYPASS_EXPRESSION = "(SELECT current_setting('app.bypass_rls', true)) = 'on'"
TABLE = "replay_runs"


def upgrade() -> None:
    op.execute(f"SET LOCAL lock_timeout = '{LOCK_TIMEOUT}'")
    _create_replay_runs()
    _enable_rls(TABLE)


def downgrade() -> None:
    op.execute(f"SET LOCAL lock_timeout = '{LOCK_TIMEOUT}'")
    op.execute(f"DROP TABLE IF EXISTS {TABLE}")


def _create_replay_runs() -> None:
    op.execute(
        """
        CREATE TABLE replay_runs (
            id               uuid PRIMARY KEY,
            project_id       uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
            source_trace_id  text NOT NULL,
            source_span_id   text NOT NULL,
            requested_by     uuid REFERENCES users (id) ON DELETE SET NULL,
            credential_id    uuid REFERENCES provider_credentials (id) ON DELETE SET NULL,
            model            text NOT NULL,
            fidelity         text NOT NULL
                CONSTRAINT replay_runs_fidelity_check
                CHECK (fidelity IN ('exact', 'modified', 'messages_only')),
            changed          text[] NOT NULL DEFAULT '{}',
            status           text NOT NULL
                CONSTRAINT replay_runs_status_check
                CHECK (status IN ('running', 'done', 'failed')),
            error            text
                CONSTRAINT replay_runs_error_check
                CHECK (char_length(error) <= 500),
            reserved_usd     numeric(14, 8) NOT NULL DEFAULT 0
                CONSTRAINT replay_runs_reserved_usd_check
                CHECK (reserved_usd >= 0),
            cost_usd         numeric(14, 8) NOT NULL DEFAULT 0
                CONSTRAINT replay_runs_cost_usd_check
                CHECK (cost_usd >= 0),
            result_trace_id  text,
            result_span_id   text,
            started_at       timestamptz NOT NULL,
            heartbeat_at     timestamptz,
            finished_at      timestamptz
        )
        """
    )
    op.execute(
        "CREATE INDEX replay_runs_source_idx ON replay_runs "
        "(project_id, source_trace_id, source_span_id, started_at DESC)"
    )
    op.execute(
        "CREATE INDEX replay_runs_project_started_idx ON replay_runs (project_id, started_at DESC)"
    )
    op.execute(
        "CREATE INDEX replay_runs_running_idx ON replay_runs (project_id) WHERE status = 'running'"
    )
    op.execute("CREATE INDEX replay_runs_requested_by_idx ON replay_runs (requested_by)")


def _enable_rls(table: str) -> None:
    op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
    op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
    op.execute(
        f"CREATE POLICY {table}_project_isolation ON {table} "
        f"USING ({PROJECT_EXPRESSION}) WITH CHECK ({PROJECT_EXPRESSION})"
    )
    op.execute(
        f"CREATE POLICY {table}_worker_bypass ON {table} "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )
